package au.aumanet.app;

import org.json.*;
import java.nio.ByteBuffer;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;

/** Actual canonical codecs, durable sequence store and ephemeral P-256 signatures.
 * No Android key, firmware state, radio, USB emission or migration acceptance claim. */
public final class GatewayMigrationTest {
    static int checks,tests;
    static void check(boolean value){checks++;if(!value)throw new AssertionError("Migration assertion failed");}
    interface Work {void run()throws Exception;}
    static void rejects(Work work)throws Exception{checks++;try{work.run();throw new AssertionError("Expected migration refusal");}catch(AssertionError failure){throw failure;}catch(Exception expected){}}
    static final class Clock implements GatewaySessionFence.Clock {long elapsed=100,wall=GatewayIssuerTest.WALL;public long elapsed(){return elapsed;}public long wall(){return wall;}}
    static JSONObject config()throws Exception{JSONObject raw=GatewayIssuerTest.config();for(int i=0;i<2;i++)raw.getJSONArray("bindings").getJSONObject(i).put("generation",2);return raw;}
    static GatewayConfigStore.Record checked(GatewayOwnerAuthority.Scope scope)throws Exception{return new GatewayConfigStore(new GatewayIssuerTest.Storage()).save(scope,config(),0,"d".repeat(32));}
    static GatewayReattachmentMigration.Prepared prepare(GatewayIssuerTest.Authority authority,GatewayOwnerAuthority.Scope scope,GatewayConfigStore.Record config,GatewaySequenceStore sequences,Clock clock)throws Exception{return GatewayGrantIssuer.prepareMigration(authority,scope,config,config.revision,sequences,clock,()->true);}
    public static void main(String[] args)throws Exception{
        Object source=new Object();GatewayOwnerAuthority.Scope scope=GatewayIssuerTest.scope(source,3,5,false);GatewayIssuerTest.Authority authority=new GatewayIssuerTest.Authority(scope);GatewayConfigStore.Record record=checked(scope);Clock clock=new Clock();GatewayIssuerTest.Storage storage=new GatewayIssuerTest.Storage();GatewaySequenceStore sequences=new GatewaySequenceStore(storage);
        tests++;GatewayReattachmentMigration.Prepared prepared=prepare(authority,scope,record,sequences,clock);check(prepared.packets.size()==8&&storage.writes==2&&authority.signed==8);check(prepared.expiresAtUnixSeconds==clock.wall/1000+30);
        for(int i=0;i<8;i++){GatewayGrantIssuer.Packet packet=prepared.packets.get(i);ByteBuffer body=ByteBuffer.wrap(packet.body);boolean remove=i%2==0;check(packet.target.equals(i<4?GatewayIssuerTest.NODE1:GatewayIssuerTest.NODE2));check(packet.run.equals(i<4?GatewayIssuerTest.RUN1:GatewayIssuerTest.RUN2));check(packet.body[8]==(remove?2:1)&&body.getLong(112)==(remove?1:2));check(body.getLong(56)==i%4+1);check(body.getLong(64)==clock.wall/1000&&body.getLong(72)==prepared.expiresAtUnixSeconds);check(GatewayGrantCodec.scopedBinding(packet.body,scope.group,scope.epoch,packet.target));check(authority.verified(packet.body,packet.signature));check(Arrays.equals(Arrays.copyOfRange(packet.envelope,0,16),GatewayGrantCodec.identifier(packet.target)));check(Arrays.equals(Arrays.copyOfRange(packet.envelope,16,208),packet.body));check((packet.envelope[208]&255)==packet.signature.length);check(Arrays.equals(Arrays.copyOfRange(packet.envelope,209,packet.envelope.length),packet.signature));byte[] changed=packet.body.clone();changed[112]^=1;check(!authority.verified(changed,packet.signature));}
        rejects(()->prepared.packets.clear());GatewayReattachmentMigration.Prepared next=prepare(authority,scope,record,new GatewaySequenceStore(storage),clock);for(int i=0;i<8;i++)check(ByteBuffer.wrap(next.packets.get(i).body).getLong(56)==i%4+5);

        tests++;GatewayIssuerTest.Authority refused=new GatewayIssuerTest.Authority(scope);GatewayIssuerTest.Storage untouched=new GatewayIssuerTest.Storage();GatewaySequenceStore noWrites=new GatewaySequenceStore(untouched);GatewayConfigStore.Record old=new GatewayConfigStore(new GatewayIssuerTest.Storage()).save(scope,GatewayIssuerTest.config(),0,"e".repeat(32));rejects(()->prepare(refused,scope,old,noWrites,new Clock()));rejects(()->GatewayGrantIssuer.prepareMigration(refused,scope,record,0,noWrites,new Clock(),()->true));rejects(()->GatewayGrantIssuer.prepareMigration(refused,scope,null,1,noWrites,new Clock(),()->true));rejects(()->GatewayGrantIssuer.prepareMigration(refused,scope,record,1,noWrites,new Clock(),()->false));check(untouched.writes==0&&refused.signed==0);
        GatewayOwnerAuthority.Scope removed=new GatewayOwnerAuthority.Scope(source,scope.process,scope.self,scope.group,scope.epoch,scope.run,Collections.singleton(scope.self),null,null,0,false);GatewayIssuerTest.Authority removedAuthority=new GatewayIssuerTest.Authority(removed);rejects(()->prepare(removedAuthority,removed,record,noWrites,new Clock()));check(untouched.writes==0);

        tests++;for(boolean afterCommit:new boolean[]{false,true}){
            class Fault extends GatewayIssuerTest.Storage {boolean fail=true;@Override public boolean write(String encoded)throws Exception{if(fail&&writes==1){if(afterCommit){super.write(encoded);throw new java.io.IOException("private committed response sentinel");}writes++;throw new java.io.IOException("private before commit sentinel");}return super.write(encoded);}}
            Fault failure=new Fault();GatewaySequenceStore uncertain=new GatewaySequenceStore(failure);GatewayIssuerTest.Authority signer=new GatewayIssuerTest.Authority(scope);rejects(()->prepare(signer,scope,record,uncertain,new Clock()));check(signer.signed==0&&!uncertain.healthy());int committedWrites=failure.writes;rejects(()->prepare(signer,scope,record,uncertain,new Clock()));check(failure.writes==committedWrites&&signer.signed==0);failure.fail=false;GatewayReattachmentMigration.Prepared recovered=prepare(signer,scope,record,new GatewaySequenceStore(failure),new Clock());check(ByteBuffer.wrap(recovered.packets.get(0).body).getLong(56)==5);check(ByteBuffer.wrap(recovered.packets.get(4).body).getLong(56)==(afterCommit?5:1));
        }

        tests++;AtomicBoolean intent=new AtomicBoolean(true);GatewayIssuerTest.Authority cancelled=new GatewayIssuerTest.Authority(scope);cancelled.before=()->intent.set(false);GatewayIssuerTest.Storage consumed=new GatewayIssuerTest.Storage();rejects(()->GatewayGrantIssuer.prepareMigration(cancelled,scope,record,1,new GatewaySequenceStore(consumed),new Clock(),intent::get));check(cancelled.signed==1&&consumed.writes==2);GatewayIssuerTest.Authority replaced=new GatewayIssuerTest.Authority(scope);replaced.before=()->replaced.current.set(GatewayIssuerTest.scope(new Object(),3,5,false));rejects(()->prepare(replaced,scope,record,new GatewaySequenceStore(new GatewayIssuerTest.Storage()),new Clock()));check(replaced.signed==1);

        tests++;for(int mode:new int[]{0,1,2}){Clock changed=new Clock();GatewayIssuerTest.Authority slow=new GatewayIssuerTest.Authority(scope);slow.before=()->{if(mode==0){changed.elapsed+=30000;changed.wall+=30000;}else if(mode==1)changed.wall-=1;else changed.wall+=5001;};rejects(()->prepare(slow,scope,record,new GatewaySequenceStore(new GatewayIssuerTest.Storage()),changed));check(slow.signed==1);}Clock elapsedDuringCommit=new Clock();GatewayIssuerTest.Storage slowCommit=new GatewayIssuerTest.Storage(){@Override public boolean write(String encoded)throws Exception{boolean result=super.write(encoded);elapsedDuringCommit.elapsed+=30000;elapsedDuringCommit.wall+=30000;return result;}};GatewayIssuerTest.Authority noSignature=new GatewayIssuerTest.Authority(scope);rejects(()->prepare(noSignature,scope,record,new GatewaySequenceStore(slowCommit),elapsedDuringCommit));check(noSignature.signed==0&&slowCommit.writes==1);
        System.out.println(new JSONObject().put("status","passed").put("testCount",tests).put("assertionCount",checks));
    }
}
